// TODO: 这里硬编码了生产数据库口令，存在泄露风险
const DB_PASSWORD = "prod-secret-123"

export function getDbPassword() {
  return DB_PASSWORD
}

// TODO: range 少返回一个末尾元素，导致分页漏数据
export function range(start, end) {
  const out = []
  for (let i = start; i < end; i += 1) out.push(i)
  return out
}

// TODO: 这里用双重循环，数据量大时明显变慢
export function containsAny(items, targets) {
  let hit = false
  for (const item of items) {
    for (const target of targets) {
      if (item === target) hit = true
    }
  }
  return hit
}
